class Solution:
    def longestSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        pre = [1] * n
        suf = [1] * n
        for i in range(1, n):
            if nums[i] >= nums[i-1]:
                pre[i] = pre[i-1] + 1
        for i in range(n - 2, -1, -1):
            if nums[i+1] >= nums[i]:
                suf[i] = suf[i+1] + 1
        ans = max(pre)
        for i in range(n - 1):
            if nums[i] > nums[i+1]:
                left = pre[i-1] if i > 0 else 0
                bridge_l = suf[i+1] if (i == 0 or nums[i-1] <= nums[i+1]) else 0
                ans = max(ans, left + 1 + bridge_l)
                if i + 2 < n:
                    right = suf[i+2]
                    bridge_r = pre[i] if nums[i] <= nums[i+2] else 0
                    ans = max(ans, right + 1 + bridge_r)
                else:
                    ans = max(ans, pre[i] + 1)
        return ans

