        vector<int> pre(n, 1), suf(n, 1);
        for (int i = 1; i < n; i++)
            if (nums[i] >= nums[i-1]) pre[i] = pre[i-1] + 1;
        for (int i = n - 2; i >= 0; i--)
            if (nums[i+1] >= nums[i]) suf[i] = suf[i+1] + 1;
        int ans = *max_element(pre.begin(), pre.end());
        for (int i = 0; i + 1 < n; i++) {
