class Solution {
    public int longestSubarray(int[] nums) {
        int n = nums.length;
        int[] pre = new int[n], suf = new int[n];
        java.util.Arrays.fill(pre, 1); java.util.Arrays.fill(suf, 1);
        for (int i = 1; i < n; i++)
            if (nums[i] >= nums[i-1]) pre[i] = pre[i-1] + 1;
        for (int i = n - 2; i >= 0; i--)
            if (nums[i+1] >= nums[i]) suf[i] = suf[i+1] + 1;
        int ans = java.util.Arrays.stream(pre).max().getAsInt();
        for (int i = 0; i + 1 < n; i++) {
            if (nums[i] > nums[i+1]) {
                int left = i > 0 ? pre[i-1] : 0;
                int bl = (i == 0 || nums[i-1] <= nums[i+1]) ? suf[i+1] : 0;
                ans = Math.max(ans, left + 1 + bl);
                if (i + 2 < n) {
                    int br = nums[i] <= nums[i+2] ? pre[i] : 0;
                    ans = Math.max(ans, suf[i+2] + 1 + br);
                } else {
                    ans = Math.max(ans, pre[i] + 1);
                }
            }
        }
        return ans;
    }
}

