var longestSubarray = function(nums) {
    const n = nums.length;
    const pre = new Array(n).fill(1), suf = new Array(n).fill(1);
    for (let i = 1; i < n; i++)
        if (nums[i] >= nums[i-1]) pre[i] = pre[i-1] + 1;
    for (let i = n - 2; i >= 0; i--)
        if (nums[i+1] >= nums[i]) suf[i] = suf[i+1] + 1;
    let ans = Math.max(...pre);
    for (let i = 0; i + 1 < n; i++) {
        if (nums[i] > nums[i+1]) {
            const left = i > 0 ? pre[i-1] : 0;
            const bl = (i === 0 || nums[i-1] <= nums[i+1]) ? suf[i+1] : 0;
            ans = Math.max(ans, left + 1 + bl);
            if (i + 2 < n) {
                const br = nums[i] <= nums[i+2] ? pre[i] : 0;
                ans = Math.max(ans, suf[i+2] + 1 + br);
            } else {
                ans = Math.max(ans, pre[i] + 1);
            }
        }
    }
    return ans;
};
